@param([Parameter(Mandatory=$true)][string]$InputPath,[string]$OutputDir="$PSScriptRoot\output",[ValidateSet(2,4)][int]$Scale=2,[ValidateSet("tiny","tiny-long")][string]$Mode="tiny-long",[int]$TileSize=256,[int]$Overlap=24,[switch]$UseHfMirror)
$ErrorActionPreference="Stop"; $FlashVsrDir=$PSScriptRoot; $PythonExe=if($env:FLASHVSR_PYTHON){$env:FLASHVSR_PYTHON}else{"$FlashVsrDir\..\Miniconda3\envs\flashvsr\python.exe"}; if(!(Test-Path $InputPath)){throw "Input not found"}; if(!(Test-Path $PythonExe)){throw "Python not found"}; New-Item -ItemType Directory -Force $OutputDir|Out-Null; $FfmpegDir=& $PythonExe -c "import imageio_ffmpeg,os; print(os.path.dirname(imageio_ffmpeg.get_ffmpeg_exe()))"; $env:Path="$FfmpegDir;$env:Path"; if($UseHfMirror){$env:HF_ENDPOINT="https://hf-mirror.com"}; $mem=(Get-CimInstance Win32_OperatingSystem).FreePhysicalMemory*1KB; if($mem -lt 4GB -and $Mode -eq "tiny"){Write-Warning "Low RAM; switching to tiny-long";$Mode="tiny-long"}; $ok=& $PythonExe -c "import torch; print(torch.cuda.is_available())"; if($ok -notmatch "True"){throw "PyTorch cannot see CUDA"}; Push-Location $FlashVsrDir; try{& $PythonExe run.py -i $InputPath -s $Scale -m $Mode --tiled-dit --tiled-vae --tile-size $TileSize --overlap $Overlap --unload-dit -a sage -t bf16 -d cuda:0 $OutputDir; if($LASTEXITCODE){throw "FlashVSR failed"}}finally{Pop-Location}; Write-Host "Finished; original input unchanged"